{"explanation":"Picture x² as a square, and split 6x into two strips of area 3x, each with width 3. Placing these along two sides leaves a 3 × 3 corner missing; adding its area, 9, makes a square with side x + 3. Therefore x² + 6x + 9 = (x + 3)², so x² + 6x = (x + 3)² − 9.","manimCode":"let x = 2.5;
let cornerFilled = false;
const unit = 0.65;
const left = -4.5;
const bottom = -2.1;
const point = (u, v) => [left + unit * u, bottom + unit * v, 0];
const box = (u, v, w, h) => [point(u, v), point(u + w, v), point(u + w, v + h), point(u, v + h)];

const title = new Text({ text: 'Completing the square', fontSize: 34, color: WHITE });
title.moveTo([0, 3.2, 0]);
const squareArea = new Polygon({ vertices: box(0, 0, x, x), color: BLUE });
const topStrip = new Polygon({ vertices: box(0, x, x, 3), color: TEAL });
const rightStrip = new Polygon({ vertices: box(x, 0, 3, x), color: TEAL });
const corner = new Polygon({ vertices: box(x, x, 3, 3), color: GOLD });
squareArea.setFill(BLUE, 0.35);
topStrip.setFill(TEAL, 0.35);
rightStrip.setFill(TEAL, 0.35);

const squareLabel = new Text({ text: 'x²', fontSize: 26, color: BLUE_A });
const topLabel = new Text({ text: '3x', fontSize: 24, color: WHITE });
const rightLabel = new Text({ text: '3x', fontSize: 24, color: WHITE });
const cornerLabel = new Text({ text: '+9', fontSize: 28, color: GOLD });
const xLabel = new Text({ text: 'x', fontSize: 22, color: WHITE });
const threeLabel = new Text({ text: '3', fontSize: 22, color: TEAL });
const handle = new Dot({ point: point(x, x), radius: 0.13, color: WHITE });

const valueLabel = new Text({ text: '', fontSize: 25, color: WHITE });
valueLabel.moveTo([3.4, 1.85, 0]);
const originalLabel = new Text({ text: '', fontSize: 23, color: BLUE_A });
originalLabel.moveTo([3.4, 1.15, 0]);
const addedLabel = new Text({ text: '', fontSize: 23, color: GOLD });
addedLabel.moveTo([3.4, 0.45, 0]);
const totalLabel = new Text({ text: '', fontSize: 23, color: WHITE });
totalLabel.moveTo([3.4, -0.25, 0]);
const sideLabel = new Text({ text: '', fontSize: 23, color: GRAY });
sideLabel.moveTo([3.4, -0.95, 0]);
const cornerHint = new Text({ text: 'Click the gold corner', fontSize: 20, color: GOLD });
cornerHint.moveTo([3.4, -1.8, 0]);

const identity = new MathTex({ latex: 'x^2 + 6x = (x+3)^2 - 9', color: WHITE });
await identity.waitForRender();
identity.moveTo([0, -2.95, 0]);
const hint = new Text({ text: 'Drag the white point to resize x · Click the gold corner to add or remove 9', fontSize: 19, color: GRAY });
hint.moveTo([0, -3.5, 0]);

function update() {
  squareArea.setVertices(box(0, 0, x, x));
  topStrip.setVertices(box(0, x, x, 3));
  rightStrip.setVertices(box(x, 0, 3, x));
  corner.setVertices(box(x, x, 3, 3));
  corner.setFill(GOLD, cornerFilled ? 0.5 : 0.04);
  squareLabel.moveTo(point(x / 2, x / 2));
  topLabel.moveTo(point(x / 2, x + 1.5));
  rightLabel.moveTo(point(x + 1.5, x / 2));
  cornerLabel.moveTo(point(x + 1.5, x + 1.5));
  cornerLabel.setText(cornerFilled ? '9' : '+9');
  xLabel.moveTo(point(x / 2, -0.35));
  threeLabel.moveTo(point(x + 1.5, -0.35));
  handle.moveTo(point(x, x));
  const original = x * x + 6 * x;
  valueLabel.setText('x = ' + x.toFixed(2));
  originalLabel.setText('x² + 6x = ' + original.toFixed(2));
  addedLabel.setText(cornerFilled ? 'Added corner: 3 × 3 = 9' : 'Missing corner: 3 × 3 = 9');
  totalLabel.setText(cornerFilled ? 'Full area = ' + (original + 9).toFixed(2) : 'L-shaped area = ' + original.toFixed(2));
  sideLabel.setText('Full square side: x + 3');
  cornerHint.setText(cornerFilled ? 'Click corner to subtract 9' : 'Click corner to add 9');
}
update();
scene.add(title);
await scene.play(new AnimationGroup([new DrawBorderThenFill(squareArea), new DrawBorderThenFill(topStrip), new DrawBorderThenFill(rightStrip)]));
scene.add(corner, squareLabel, topLabel, rightLabel, cornerLabel, xLabel, threeLabel, handle, valueLabel, originalLabel, addedLabel, totalLabel, sideLabel, cornerHint, identity, hint);

makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  const horizontal = (pos[0] - left) / unit;
  const vertical = (pos[1] - bottom) / unit;
  x = Math.max(1.5, Math.min(4, (horizontal + vertical) / 2));
  update();
} });
makeClickable(corner, scene, { onClick: () => {
  cornerFilled = !cornerFilled;
  update();
} });
await scene.wait(999999);"}

